import React, { useState, useEffect } from 'react';
import { Box, TextField, Button, Typography, Grid, Paper } from '@mui/material';
import { Bar } from 'react-chartjs-2';
import 'chart.js/auto';
import Papa from 'papaparse'; // Import PapaParse for CSV handling

function Predict() {
    const [formData, setFormData] = useState({
        location: '',
        size: '',
        total_sqft: '',
        bathrooms: '', // New bathroom input
    });
    const [predictions, setPredictions] = useState(null);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(null);
    const [dataFromCSV, setDataFromCSV] = useState([]); // State for CSV data

    useEffect(() => {
        // Load CSV data when the component mounts
        const loadData = async () => {
            const response = await fetch('/path/to/cleaned_real_estate_data.csv'); // Adjust the path accordingly
            const csvData = await response.text();
            const parsedData = Papa.parse(csvData, { header: true });
            setDataFromCSV(parsedData.data); // Assuming each entry has a 'price' field
        };
        loadData();
    }, []);

    const handleChange = (e) => {
        setFormData({
            ...formData,
            [e.target.name]: e.target.value
        });
    };

    const handlePredict = async () => {
        setLoading(true);
        setError(null);

        try {
            const response = await fetch('http://localhost:8000/predict', {  // Replace with your API URL
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    location: formData.location,
                    size: parseFloat(formData.size),
                    total_sqft: parseFloat(formData.total_sqft),
                    bathrooms: parseInt(formData.bathrooms), // Include bathrooms in the request
                })
            });

            if (!response.ok) {
                throw new Error('Failed to fetch predictions');
            }

            const data = await response.json();
            setPredictions(data.prediction); // Assuming 'prediction' is returned by the API
        } catch (err) {
            setError(err.message);
        } finally {
            setLoading(false);
        }
    };

    // Prepare data for the bar chart
    const barChartData = {
        labels: ['Current Prediction', ...dataFromCSV.map(item => item.location)], // Add other locations from CSV
        datasets: [
            {
                label: 'Price Prediction',
                data: [
                    predictions ? predictions : 0,
                    ...dataFromCSV.map(item => parseFloat(item.price)) // Assuming 'price' is a field in your CSV
                ],
                backgroundColor: ['#3b82f6', '#ff6384'] // Colors for bars
            }
        ]
    };

    return (
        <Box sx={{ padding: '50px', maxWidth: '1500px', margin: '0 auto' }}>
            <Typography variant="h4" gutterBottom align="center">
                Predict With Us
            </Typography>

            <Grid container spacing={6} justifyContent="center" alignItems="flex-start">
                <Grid item xs={12} md={5}>
                    <Box component="form" sx={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
                        <TextField label="Location"
                            name="location"
                            value={formData.location}
                            onChange={handleChange}
                            required
                        />

                        <TextField label="Size (e.g., 3 BHK)"
                            name="size"
                            value={formData.size}
                            onChange={handleChange}
                            required
                        />

                        <TextField label="Total Square Feet"
                            name="total_sqft"
                            value={formData.total_sqft}
                            onChange={handleChange}
                            type="number"
                            required
                        />

                        <TextField label="Bathrooms"
                            name="bathrooms" // New input field
                            value={formData.bathrooms}
                            onChange={handleChange}
                            type="number"
                            required
                        />

                        <Button
                            variant="contained"
                            onClick={handlePredict}
                            disabled={loading}
                        >
                            {loading ? 'Loading...' : 'Get Predictions'}
                        </Button>
                        {error && <Typography color="error">{error}</Typography>}
                    </Box>
                </Grid>

                {predictions && (
                    <Grid item xs={12} md={5}>
                        <Paper elevation={3} sx={{ padding: '20px', textAlign: 'center' }}>
                            <Typography variant="h6">
                                Predicted Price: ${predictions.toFixed(2)}
                            </Typography>
                        </Paper>
                    </Grid>
                )}
            </Grid>

            {/* Optional Bar Chart Visualization */}
            {predictions && (
                <Box sx={{ marginTop: '50px', textAlign: 'center' }}>
                    <Typography variant="h6">
                        Prediction Visualization
                    </Typography>
                    <Box sx={{ height: '400px' }}>
                        <Bar data={barChartData} options={{ responsive: true, maintainAspectRatio: false }} />
                    </Box>
                </Box>
            )}
        </Box>
    );
}

export default Predict;
